import{_ as a,o as t,c as n,a0 as o}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"ADR 0006: The control plane polls herdr for agent state","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0006-the-control-plane-polls-herdr.md","filePath":"adr/0006-the-control-plane-polls-herdr.md"}'),r={name:"adr/0006-the-control-plane-polls-herdr.md"};function l(s,e,i,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0006-the-control-plane-polls-herdr-for-agent-state" tabindex="-1">ADR 0006: The control plane polls herdr for agent state <a class="header-anchor" href="#adr-0006-the-control-plane-polls-herdr-for-agent-state" aria-label="Permalink to &quot;ADR 0006: The control plane polls herdr for agent state&quot;">​</a></h1><p>Status: accepted Date: 2026-08-31</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The control plane must observe each handed-off agent&#39;s lifecycle (working, settled, blocked, missing) without blocking its TUI. herdr offers a blocking <code>agent wait</code> command per agent and a one-shot <code>agent list</code> of all agents. The same observation also feeds the parallel limit count.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>A single timer polls <code>herdr agent list</code> on a configurable interval, 5 seconds by default. The handoff record stores the pane id (plus tab and workspace id) when the handoff starts, and every later read, focus, and cleanup targets that pane id.</p><p>The considered alternative:</p><ul><li>One <code>herdr agent wait</code> child process per in-flight ticket. Rejected: one process per ticket, a second egress pattern beside the command runner, and no single view from which the parallel limit can count. One list call carries every agent, so state transitions and the limit share one observation.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A state change lags the real event by up to one interval.</li><li>The pane id must be captured at handoff time: herdr&#39;s list result does not expose the agent name, so the name alone is not a reliable handle.</li><li>The fake runner tests pin the poll command sequence like every other herdr exchange.</li></ul>',10)])])}const f=a(r,[["render",l]]);export{u as __pageData,f as default};
